int BasicVehicleContainerHighFrequency::OER_encode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf) const
{
  if (!is_bound()) {
  TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND,
    "Encoding an unbound record value.");
  return -1;
  }
  char c = 0;
  if (field_accelerationControl.is_present()) {
    c |= 128;
  }
  if (field_lanePosition.is_present()) {
    c |= 64;
  }
  if (field_steeringWheelAngle.is_present()) {
    c |= 32;
  }
  if (field_lateralAcceleration.is_present()) {
    c |= 16;
  }
  if (field_verticalAcceleration.is_present()) {
    c |= 8;
  }
  if (field_performanceClass.is_present()) {
    c |= 4;
  }
  if (field_cenDsrcTollingZone.is_present()) {
    c |= 2;
  }
  p_buf.put_c(c);
  field_heading.OER_encode(BasicVehicleContainerHighFrequency_heading_descr_, p_buf);
  field_speed.OER_encode(BasicVehicleContainerHighFrequency_speed_descr_, p_buf);
  field_driveDirection.OER_encode(BasicVehicleContainerHighFrequency_driveDirection_descr_, p_buf);
  field_vehicleLength.OER_encode(BasicVehicleContainerHighFrequency_vehicleLength_descr_, p_buf);
  field_vehicleWidth.OER_encode(BasicVehicleContainerHighFrequency_vehicleWidth_descr_, p_buf);
  field_longitudinalAcceleration.OER_encode(BasicVehicleContainerHighFrequency_longitudinalAcceleration_descr_, p_buf);
  field_curvature.OER_encode(BasicVehicleContainerHighFrequency_curvature_descr_, p_buf);
  field_curvatureCalculationMode.OER_encode(BasicVehicleContainerHighFrequency_curvatureCalculationMode_descr_, p_buf);
  field_yawRate.OER_encode(BasicVehicleContainerHighFrequency_yawRate_descr_, p_buf);
  if (field_accelerationControl.is_present())
    field_accelerationControl.OER_encode(BasicVehicleContainerHighFrequency_accelerationControl_descr_, p_buf);
  if (field_lanePosition.is_present())
    field_lanePosition.OER_encode(BasicVehicleContainerHighFrequency_lanePosition_descr_, p_buf);
  if (field_steeringWheelAngle.is_present())
    field_steeringWheelAngle.OER_encode(BasicVehicleContainerHighFrequency_steeringWheelAngle_descr_, p_buf);
  if (field_lateralAcceleration.is_present())
    field_lateralAcceleration.OER_encode(BasicVehicleContainerHighFrequency_lateralAcceleration_descr_, p_buf);
  if (field_verticalAcceleration.is_present())
    field_verticalAcceleration.OER_encode(BasicVehicleContainerHighFrequency_verticalAcceleration_descr_, p_buf);
  if (field_performanceClass.is_present())
    field_performanceClass.OER_encode(BasicVehicleContainerHighFrequency_performanceClass_descr_, p_buf);
  if (field_cenDsrcTollingZone.is_present())
    field_cenDsrcTollingZone.OER_encode(BasicVehicleContainerHighFrequency_cenDsrcTollingZone_descr_, p_buf);
  return 0;
}

