{
if (!is_bound()) {
TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, "Encoding an unbound SEQUENCE value.");
return;
}
field_header.PER_encode(CAM_header_descr_, p_buf, p_options);
field_cam.PER_encode(CAM_cam_descr_, p_buf, p_options);
}

void CAM::PER_decode(const TTCN_Typedescriptor_t& p_td, TTCN_Buffer& p_buf, int p_options)
{
clean_up();
field_header.PER_decode(CAM_header_descr_, p_buf, p_options);
field_cam.PER_decode(CAM_cam_descr_, p_buf, p_options);
}


